    94→	if err != nil {
    95→		return nil, err
    96→	}
    97→	if err := file.WriteFile(gethJsonPath, b); err != nil {
    98→		return nil, err
    99→	}
   100→
   101→	// write the same thing to the logs dir for inspection
   102→	gethJsonLogPath := e2e.TestParams.Logfile("genesis.json")
   103→	if err := file.WriteFile(gethJsonLogPath, b); err != nil {
   104→		return nil, err
   105→	}
   106→
   107→	initCmd := exec.CommandContext(ctx, binaryPath, "init", fmt.Sprintf("--datadir=%s", m.DataDir()), gethJsonPath) // #nosec G204 -- Safe
   108→
   109→	// redirect stderr to a log file
   110→	initFile, err := helpers.DeleteAndCreatePath(e2e.TestParams.Logfile("eth1-init_miner.log"))
   111→	if err != nil {
   112→		return nil, err
   113→	}
   114→	initCmd.Stderr = initFile
   115→
   116→	// run init command and wait until it exits. this will initialize the geth node (required before starting).
   117→	if err = initCmd.Start(); err != nil {
   118→		return nil, err
   119→	}
   120→	if err = initCmd.Wait(); err != nil {
   121→		return nil, err
   122→	}
   123→
   124→	pwFile := m.DataDir("keystore", minerPasswordFile)
   125→	args := []string{
   126→		"--nat=none", // disable nat traversal in e2e, it is failure prone and not needed
   127→		fmt.Sprintf("--datadir=%s", m.DataDir()),
   128→		fmt.Sprintf("--http.port=%d", e2e.TestParams.Ports.Eth1RPCPort),
   129→		fmt.Sprintf("--ws.port=%d", e2e.TestParams.Ports.Eth1WSPort),
   130→		fmt.Sprintf("--authrpc.port=%d", e2e.TestParams.Ports.Eth1AuthRPCPort),
   131→		fmt.Sprintf("--bootnodes=%s", m.bootstrapEnr),
