   188→// Start runs a mining ETH1 node.
   189→// The miner is responsible for moving the ETH1 chain forward and for deploying the deposit contract.
   190→func (m *Miner) Start(ctx context.Context) error {
   191→	// give the miner start a couple of tries, since the p2p networking check is flaky
   192→	var retryErr error
   193→	var minerLog *os.File
   194→	for attempt := 0; attempt < 3; attempt++ {
   195→		minerLog, retryErr = m.initAttempt(ctx, attempt)
   196→		if retryErr == nil {
   197→			log.Infof("Miner started after %d retries", attempt)
   198→			break
   199→		}
   200→	}
   201→	if retryErr != nil {
   202→		return retryErr
   203→	}
   204→
   205→	enode, err := enodeFromLogFile(minerLog.Name())
   206→	if err != nil {
   207→		return err
   208→	}
   209→	enode = "enode://" + enode + "@127.0.0.1:" + fmt.Sprintf("%d", e2e.TestParams.Ports.Eth1Port)
   210→	m.enr = enode
   211→	log.Infof("Communicated enode. Enode is %s", enode)
   212→
   213→	// Connect to the started geth dev chain.
   214→	client, err := rpc.DialHTTP(e2e.TestParams.Eth1RPCURL(e2e.MinerComponentOffset).String())
   215→	if err != nil {
   216→		return fmt.Errorf("failed to connect to ipc: %w", err)
   217→	}
   218→	web3 := ethclient.NewClient(client)
   219→	block, err := web3.BlockByNumber(ctx, nil)
   220→	if err != nil {
   221→		return err
   222→	}
   223→	log.Infof("genesis block timestamp=%d", block.Time())
   224→	eth1BlockHash := block.Hash()
   225→	e2e.TestParams.Eth1GenesisBlock = block
   226→	log.Infof("miner says genesis block root=%#x", eth1BlockHash)
   227→	cAddr := common.HexToAddress(params.BeaconConfig().DepositContractAddress)
   228→	code, err := web3.CodeAt(ctx, cAddr, nil)
   229→	if err != nil {
   230→		return err
   231→	}
   232→	log.Infof("contract code size = %d", len(code))
   233→	depositContractCaller, err := contracts.NewDepositContractCaller(cAddr, web3)
   234→	if err != nil {
   235→		return err
   236→	}
   237→	dCount, err := depositContractCaller.GetDepositCount(&bind.CallOpts{})
   238→	if err != nil {
   239→		log.Error("Failed to call get_deposit_count method of deposit contract")
   240→		return err
   241→	}
   242→	log.Infof("deposit contract count=%d", dCount)
   243→
   244→	// Mark node as ready.
   245→	close(m.started)
   246→	return m.cmd.Wait()
   247→}
