    13→)
    14→
    15→// SparseMerkleTrie implements a sparse, general purpose Merkle trie to be used
    16→// across Ethereum consensus functionality.
    17→type SparseMerkleTrie struct {
    18→	depth         uint
    19→	branches      [][][]byte
    20→	originalItems [][]byte // list of provided items before hashing them into leaves.
    21→}
    22→
    23→// NewTrie returns a new merkle trie filled with zerohashes to use.
    24→func NewTrie(depth uint64) (*SparseMerkleTrie, error) {
    25→	var zeroBytes [32]byte
    26→	items := [][]byte{zeroBytes[:]}
    27→	return GenerateTrieFromItems(items, depth)
    28→}
    29→
    30→// CreateTrieFromProto creates a Sparse Merkle Trie from its corresponding merkle trie.
    31→func CreateTrieFromProto(trieObj *protodb.SparseMerkleTrie) (*SparseMerkleTrie, error) {
    32→	trie := &SparseMerkleTrie{
    33→		depth:         uint(trieObj.Depth),
    34→		originalItems: trieObj.OriginalItems,
    35→	}
    36→	branches := make([][][]byte, len(trieObj.Layers))
    37→	for i, layer := range trieObj.Layers {
    38→		branches[i] = layer.Layer
    39→	}
    40→	trie.branches = branches
    41→
    42→	if err := trie.validate(); err != nil {
    43→		return nil, errors.Wrap(err, "invalid sparse merkle trie")
    44→	}
    45→
    46→	return trie, nil
    47→}
    48→
    49→func (m *SparseMerkleTrie) validate() error {
    50→	if len(m.branches) == 0 {
    51→		return errors.New("no branches")
    52→	}
    53→	if len(m.branches[len(m.branches)-1]) == 0 {
    54→		return errors.New("invalid branches provided")
    55→	}
    56→	if m.depth >= uint(len(m.branches)) {
    57→		return errors.New("depth is greater than or equal to number of branches")
    58→	}
    59→	if m.depth >= 63 {
    60→		return errors.New("supported merkle trie depth exceeded (max uint64 depth is 63, " +
    61→			"theoretical max sparse merkle trie depth is 64)") // PowerOf2 would overflow.
    62→	}
    63→
    64→	return nil
    65→}
    66→
    67→// GenerateTrieFromItems constructs a Merkle trie from a sequence of byte slices.
    68→func GenerateTrieFromItems(items [][]byte, depth uint64) (*SparseMerkleTrie, error) {
    69→	if len(items) == 0 {
    70→		return nil, errors.New("no items provided to generate Merkle trie")
    71→	}
    72→	if depth >= 63 {
    73→		return nil, errors.New("supported merkle trie depth exceeded (max uint64 depth is 63, " +
    74→			"theoretical max sparse merkle trie depth is 64)") // PowerOf2 would overflow
    75→	}
    76→
    77→	leaves := items
    78→	layers := make([][][]byte, depth+1)
    79→	transformedLeaves := make([][]byte, len(leaves))
    80→	for i := range leaves {
    81→		arr := bytesutil.ToBytes32(leaves[i])
    82→		transformedLeaves[i] = arr[:]
    83→	}
    84→	layers[0] = transformedLeaves
    85→	for i := uint64(0); i < depth; i++ {
    86→		if len(layers[i])%2 == 1 {
    87→			layers[i] = append(layers[i], ZeroHashes[i][:])
    88→		}
    89→		updatedValues := make([][]byte, 0)
    90→		for j := 0; j < len(layers[i]); j += 2 {
    91→			concat := hash.Hash(append(layers[i][j], layers[i][j+1]...))
    92→			updatedValues = append(updatedValues, concat[:])
    93→		}
    94→		layers[i+1] = updatedValues
    95→	}
    96→	return &SparseMerkleTrie{
    97→		branches:      layers,
    98→		originalItems: items,
    99→		depth:         uint(depth),
   100→	}, nil

